1	import type { Incident, Item } from "./claim-office.js";
2	import { claim, payoutCapOf, quote } from "./claim-office.js";
3	
4	// A scenario is the parsed input format: a customer and a list of steps to run
5	// against them. Running a scenario is deliberately separate from the CLI that
6	// wraps it — reading stdin, writing stdout and setting an exit status are I/O
7	// concerns, while sequencing steps is not. Keeping them apart lets the step
8	// logic be exercised without a process.
9	
10	// The scenario names a customer by years alone. Previous contracts are not
11	// given: they are derived from the step's position, since each quote step is
12	// itself a contract.
13	export type ScenarioCustomer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	// The two step kinds carry different fields, and each field is required by the
18	// kind that uses it: a quote step always has items, a claim step always names a
19	// policy and an incident. Splitting them says so, which is what lets the step
20	// runners read their fields directly instead of defaulting away absences that
21	// the input format does not actually permit.
22	export type QuoteStep = {
23	  op: "quote";
24	  items: Item[];
25	};
26	
27	export type ClaimStep = {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export type Scenario = {
36	  customer: ScenarioCustomer;
37	  steps: Step[];
38	};
39	
40	export type StepResult = {
41	  premium?: number;
42	  payout?: number;
43	  remainingCap?: number;
44	};
45	
46	// Each quote step signs one contract; a claim step does not. So "previous
47	// contracts" counts the quote steps that ran before this one, which is not the
48	// same as the step's own index once claims are interleaved.
49	const previousContractsAt = (steps: Step[], stepIndex: number): number =>
50	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
51	
52	// Takes the contract count already resolved rather than the whole step list
53	// plus an index to derive it from. A quote step's premium depends on how many
54	// contracts came before, not on the scenario those contracts sit in, and the
55	// signature now says exactly that.
56	const runQuoteStep = (
57	  customer: ScenarioCustomer,
58	  step: QuoteStep,
59	  previousContracts: number,
60	): StepResult => ({
61	  premium: quote(
62	    { yearsWithMHPCO: customer.yearsWithMHPCO, previousContracts },
63	    step.items,
64	  ),
65	});
66	
67	// A claim step names its policy by the index of the step that created it, so
68	// the items it is claiming against have to be fetched back out of the scenario.
69	const insuredItemsOf = (step: ClaimStep, steps: Step[]): Item[] => {
70	  const policyStep = steps[step.policy];
71	  if (policyStep?.op !== "quote") {
72	    throw new Error(`No policy at step index ${step.policy}`);
73	  }
74	  return policyStep.items;
75	};
76	
77	const runClaimStep = (
78	  step: ClaimStep,
79	  steps: Step[],
80	  remainingCaps: Map<number, number>,
81	): StepResult => {
82	  const insuredItems = insuredItemsOf(step, steps);
83	  const cap = remainingCaps.get(step.policy) ?? payoutCapOf(insuredItems);
84	  const result = claim(insuredItems, step.incident, cap);
85	  remainingCaps.set(step.policy, result.remainingCap);
86	  return result;
87	};
88	
89	const runStep = (
90	  customer: ScenarioCustomer,
91	  step: Step,
92	  steps: Step[],
93	  stepIndex: number,
94	  remainingCaps: Map<number, number>,
95	): StepResult =>
96	  step.op === "claim"
97	    ? runClaimStep(step, steps, remainingCaps)
98	    : runQuoteStep(customer, step, previousContractsAt(steps, stepIndex));
99	
100	export const runScenario = (scenario: Scenario): StepResult[] => {
101	  const remainingCaps = new Map<number, number>();
102	  return scenario.steps.map((step, stepIndex) =>
103	    runStep(scenario.customer, step, scenario.steps, stepIndex, remainingCaps),
104	  );
105	};
